1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { Code, ConnectError, createClient, type Interceptor } from "@connectrpc/connect";
3	import { createConnectTransport } from "@connectrpc/connect-web";
4	import { getAccessToken, hasStoredToken, isTokenExpired, REQUEST_TOKEN_EXPIRY_BUFFER_MS, setAccessToken } from "./auth-state";
5	import { AIService } from "./types/proto/api/v1/ai_service_pb";
6	import { AttachmentService } from "./types/proto/api/v1/attachment_service_pb";
7	import { AuthService } from "./types/proto/api/v1/auth_service_pb";
8	import { IdentityProviderService } from "./types/proto/api/v1/idp_service_pb";
9	import { InstanceService } from "./types/proto/api/v1/instance_service_pb";
10	import { MemoService } from "./types/proto/api/v1/memo_service_pb";
11	import { ShortcutService } from "./types/proto/api/v1/shortcut_service_pb";
12	import { UserService } from "./types/proto/api/v1/user_service_pb";
13	import { redirectOnAuthFailure } from "./utils/auth-redirect";
14	
15	interface RequestWithHeader {
16	  header: Headers;
17	}
18	
19	// ============================================================================
20	// Constants
21	// ============================================================================
22	
23	const RETRY_HEADER = "X-Retry";
24	const RETRY_HEADER_VALUE = "true";
25	
26	// ============================================================================
27	// Token Refresh State Management
28	// ============================================================================
29	
30	const createTokenRefreshManager = () => {
31	  let isRefreshing = false;
32	  let refreshPromise: Promise<void> | null = null;
33	
34	  return {
35	    async refresh(refreshFn: () => Promise<void>): Promise<void> {
36	      if (isRefreshing && refreshPromise) {
37	        return refreshPromise;
38	      }
39	
40	      isRefreshing = true;
41	      refreshPromise = refreshFn().finally(() => {
42	        isRefreshing = false;
43	        refreshPromise = null;
44	      });
45	
46	      return refreshPromise;
47	    },
48	  };
49	};
50	
51	const tokenRefreshManager = createTokenRefreshManager();
52	
53	// ============================================================================
54	// Token Refresh
55	// ============================================================================
56	
57	const fetchWithCredentials: typeof globalThis.fetch = (input, init) => {
58	  return globalThis.fetch(input, {
59	    ...init,
60	    credentials: "include",
61	  });
62	};
63	
64	// Separate transport without auth interceptor to prevent recursion
65	const refreshTransport = createConnectTransport({
66	  baseUrl: window.location.origin,
67	  useBinaryFormat: true,
68	  fetch: fetchWithCredentials,
69	  interceptors: [],
70	});
71	
72	const refreshAuthClient = createClient(AuthService, refreshTransport);
73	
74	async function doRefreshAccessToken(): Promise<void> {
75	  const response = await refreshAuthClient.refreshToken({});
76	
77	  if (!response.accessToken) {
78	    throw new ConnectError("Refresh token response missing access token", Code.Internal);
79	  }
80	
81	  const expiresAt = response.expiresAt ? timestampDate(response.expiresAt) : undefined;
82	  setAccessToken(response.accessToken, expiresAt);
83	}
84	
85	// All callers go through the manager to deduplicate concurrent refresh requests.
86	// This prevents race conditions between useTokenRefreshOnFocus (proactive refresh
87	// on tab focus) and the auth interceptor (reactive refresh on 401), which could
88	// otherwise send duplicate requests that conflict with server-side token rotation.
89	export async function refreshAccessToken(): Promise<void> {
90	  return tokenRefreshManager.refresh(doRefreshAccessToken);
91	}
92	
93	// ============================================================================
94	// Authentication Interceptor Helpers
95	// ============================================================================
96	
97	function setAuthorizationHeader(req: RequestWithHeader, token: string | null) {
98	  if (!token) return;
99	  req.header.set("Authorization", `Bearer ${token}`);
100	}
101	
102	function shouldHandleUnauthenticatedRetry(error: unknown, isRetryAttempt: boolean): boolean {
103	  if (!(error instanceof ConnectError)) {
104	    return false;
105	  }
106	  if (error.code !== Code.Unauthenticated) {
107	    return false;
108	  }
109	  if (isRetryAttempt) {
110	    return false;
111	  }
112	  return true;
113	}
114	
115	async function refreshAndGetAccessToken(): Promise<string> {
116	  await refreshAccessToken();
117	  const token = getAccessToken();
118	  if (!token) {
119	    throw new ConnectError("Token refresh succeeded but no token available", Code.Internal);
120	  }
121	  return token;
122	}
123	
124	export async function getRequestToken(): Promise<string | null> {
125	  let token = getAccessToken();
126	  if (!token) {
127	    if (!hasStoredToken()) return null;
128	    try {
129	      token = await refreshAndGetAccessToken();
130	    } catch {
131	      return null;
132	    }
133	    return token;
134	  }
135	
136	  // Preflight refresh: avoid sending requests with expired access tokens.
137	  // This is especially important for public endpoints (e.g. ListMemos), where
138	  // an expired token could otherwise be treated as anonymous and return
139	  // guest-scoped data before the reactive 401 refresh path runs.
140	  if (isTokenExpired(REQUEST_TOKEN_EXPIRY_BUFFER_MS)) {
141	    try {
142	      token = await refreshAndGetAccessToken();
143	    } catch {
144	      // Keep existing reactive 401 flow as fallback.
145	      // Protected methods still trigger refresh/redirect in the catch block below.
146	    }
147	  }
148	
149	  return token;
150	}
151	
152	// ============================================================================
153	// Authentication Interceptor
154	// ============================================================================
155	
156	const authInterceptor: Interceptor = (next) => async (req) => {
157	  const isRetryAttempt = req.header.get(RETRY_HEADER) === RETRY_HEADER_VALUE;
158	  const token = await getRequestToken();
159	  setAuthorizationHeader(req, token);
160	
161	  try {
162	    return await next(req);
163	  } catch (error) {
164	    if (!shouldHandleUnauthenticatedRetry(error, isRetryAttempt)) {
165	      throw error;
166	    }
167	
168	    try {
169	      const newToken = await refreshAndGetAccessToken();
170	      setAuthorizationHeader(req, newToken);
171	      req.header.set(RETRY_HEADER, RETRY_HEADER_VALUE);
172	      return await next(req);
173	    } catch (refreshError) {
174	      redirectOnAuthFailure();
175	      throw refreshError;
176	    }
177	  }
178	};
179	
180	// ============================================================================
181	// Transport & Service Clients
182	// ============================================================================
183	
184	const transport = createConnectTransport({
185	  baseUrl: window.location.origin,
186	  useBinaryFormat: true,
187	  fetch: fetchWithCredentials,
188	  interceptors: [authInterceptor],
189	});
190	
191	// Core service clients
192	export const instanceServiceClient = createClient(InstanceService, transport);
193	export const authServiceClient = createClient(AuthService, transport);
194	export const userServiceClient = createClient(UserService, transport);
195	
196	// Content service clients
197	export const memoServiceClient = createClient(MemoService, transport);
198	export const attachmentServiceClient = createClient(AttachmentService, transport);
199	export const aiServiceClient = createClient(AIService, transport);
200	export const shortcutServiceClient = createClient(ShortcutService, transport);
201	
202	// Configuration service clients
203	export const identityProviderServiceClient = createClient(IdentityProviderService, transport);
204

1	import { useQueryClient } from "@tanstack/react-query";
2	import { createContext, type ReactNode, useCallback, useContext, useMemo, useState } from "react";
3	import { clearAccessToken, getAccessToken } from "@/auth-state";
4	import { authServiceClient, refreshAccessToken, shortcutServiceClient, userServiceClient } from "@/connect";
5	import { userKeys } from "@/hooks/useUserQueries";
6	import type { Shortcut } from "@/types/proto/api/v1/shortcut_service_pb";
7	import type {
8	  User,
9	  UserSetting_GeneralSetting,
10	  UserSetting_TagsSetting,
11	  UserSetting_WebhooksSetting,
12	} from "@/types/proto/api/v1/user_service_pb";
13	
14	interface AuthState {
15	  currentUser: User | undefined;
16	  userGeneralSetting: UserSetting_GeneralSetting | undefined;
17	  userWebhooksSetting: UserSetting_WebhooksSetting | undefined;
18	  userTagsSetting: UserSetting_TagsSetting | undefined;
19	  shortcuts: Shortcut[];
20	  isInitialized: boolean;
21	  isLoading: boolean;
22	}
23	
24	interface AuthContextValue extends AuthState {
25	  initialize: () => Promise<void>;
26	  logout: () => Promise<void>;
27	  refetchSettings: () => Promise<void>;
28	  setCurrentUser: (user: User | undefined) => void;
29	}
30	
31	const AuthContext = createContext<AuthContextValue | null>(null);
32	
33	/** Settled auth state for a request with no valid session (init finished, not loading). */
34	const UNAUTHENTICATED_STATE: AuthState = {
35	  currentUser: undefined,
36	  userGeneralSetting: undefined,
37	  userWebhooksSetting: undefined,
38	  userTagsSetting: undefined,
39	  shortcuts: [],
40	  isInitialized: true,
41	  isLoading: false,
42	};
43	
44	export function AuthProvider({ children }: { children: ReactNode }) {
45	  const queryClient = useQueryClient();
46	  const [state, setState] = useState<AuthState>({
47	    currentUser: undefined,
48	    userGeneralSetting: undefined,
49	    userWebhooksSetting: undefined,
50	    userTagsSetting: undefined,
51	    shortcuts: [],
52	    isInitialized: false,
53	    isLoading: true,
54	  });
55	
56	  const fetchUserSettings = useCallback(async (userName: string) => {
57	    const [{ settings }, { shortcuts }] = await Promise.all([
58	      userServiceClient.listUserSettings({ parent: userName }),
59	      shortcutServiceClient.listShortcuts({ parent: userName }),
60	    ]);
61	
62	    const generalSetting = settings.find((s) => s.value.case === "generalSetting");
63	    const webhooksSetting = settings.find((s) => s.value.case === "webhooksSetting");
64	    const tagsSetting = settings.find((s) => s.value.case === "tagsSetting");
65	
66	    return {
67	      userGeneralSetting: generalSetting?.value.case === "generalSetting" ? generalSetting.value.value : undefined,
68	      userWebhooksSetting: webhooksSetting?.value.case === "webhooksSetting" ? webhooksSetting.value.value : undefined,
69	      userTagsSetting: tagsSetting?.value.case === "tagsSetting" ? tagsSetting.value.value : undefined,
70	      shortcuts,
71	    };
72	  }, []);
73	
74	  const initialize = useCallback(async () => {
75	    setState((prev) => ({ ...prev, isLoading: true }));
76	
77	    // Try to get or refresh the access token.
78	    // This handles PWA isolated storage scenarios (e.g., iOS Safari) where localStorage
79	    // may be empty but a valid HTTP-only refresh token cookie still exists.
80	    // getAccessToken() returns a cached token or loads from localStorage if valid.
81	    if (!getAccessToken()) {
82	      try {
83	        await refreshAccessToken();
84	      } catch {
85	        // Refresh failed - no valid session
86	      }
87	    }
88	
89	    // If we still don't have a token after refresh attempt, skip getCurrentUser call
90	    // to avoid unnecessary network request for unauthenticated users.
91	    if (!getAccessToken()) {
92	      setState(UNAUTHENTICATED_STATE);
93	      return;
94	    }
95	
96	    try {
97	      const { user: currentUser } = await authServiceClient.getCurrentUser({});
98	
99	      if (!currentUser) {
100	        clearAccessToken();
101	        setState(UNAUTHENTICATED_STATE);
102	        return;
103	      }
104	
105	      const settings = await fetchUserSettings(currentUser.name);
106	
107	      setState({
108	        currentUser,
109	        ...settings,
110	        isInitialized: true,
111	        isLoading: false,
112	      });
113	
114	      // Pre-populate React Query cache
115	      queryClient.setQueryData(userKeys.currentUser(), currentUser);
116	      queryClient.setQueryData(userKeys.detail(currentUser.name), currentUser);
117	    } catch (error) {
118	      console.error("Failed to initialize auth:", error);
119	      clearAccessToken();
120	      setState(UNAUTHENTICATED_STATE);
121	    }
122	  }, [fetchUserSettings, queryClient]);
123	
124	  const logout = useCallback(async () => {
125	    try {
126	      await authServiceClient.signOut({});
127	    } catch (error) {
128	      console.error("[AuthContext] Failed to sign out:", error);
129	    } finally {
130	      clearAccessToken();
131	      setState(UNAUTHENTICATED_STATE);
132	      queryClient.clear();
133	    }
134	  }, [queryClient]);
135	
136	  const refetchSettings = useCallback(async () => {
137	    const currentUserName = state.currentUser?.name;
138	    if (!currentUserName) {
139	      return;
140	    }
141	
142	    const settings = await fetchUserSettings(currentUserName);
143	    setState((prev) => {
144	      if (prev.currentUser?.name !== currentUserName) {
145	        return prev;
146	      }
147	      return { ...prev, ...settings };
148	    });
149	  }, [fetchUserSettings, state.currentUser?.name]);
150	
151	  // Sync the updated user to AuthContext and React Query cache after profile changes
152	  const setCurrentUser = useCallback(
153	    (user: User | undefined) => {
154	      const previousUser = queryClient.getQueryData<User>(userKeys.currentUser());
155	      setState((prev) => ({ ...prev, currentUser: user }));
156	      if (user) {
157	        queryClient.setQueryData(userKeys.currentUser(), user);
158	        queryClient.setQueryData(userKeys.detail(user.name), user);
159	      } else {
160	        queryClient.removeQueries({ queryKey: userKeys.currentUser(), exact: true });
161	        if (previousUser?.name) {
162	          queryClient.removeQueries({ queryKey: userKeys.detail(previousUser.name), exact: true });
163	        }
164	      }
165	    },
166	    [queryClient],
167	  );
168	
169	  // Memoize context value to prevent unnecessary re-renders of consumers
170	  const value = useMemo(
171	    () => ({
172	      ...state,
173	      initialize,
174	      logout,
175	      refetchSettings,
176	      setCurrentUser,
177	    }),
178	    [state, initialize, logout, refetchSettings, setCurrentUser],
179	  );
180	
181	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
182	}
183	
184	export function useAuth() {
185	  const context = useContext(AuthContext);
186	  if (!context) {
187	    throw new Error("useAuth must be used within AuthProvider");
188	  }
189	  return context;
190	}
191	
192	// Convenience hook for just the current user
193	export function useCurrentUserFromAuth() {
194	  const { currentUser } = useAuth();
195	  return currentUser;
196	}
