18	export const useLocalStorage = <T>(key: string, defaultValue: T): [T, (value: SetLocalStorageValue<T>) => void] => {
19	  const defaultValueRef = useRef(defaultValue);
20	  defaultValueRef.current = defaultValue;
21	
22	  const [storedValue, setStoredValue] = useState<T>(() => readLocalStorageValue(key, defaultValue));
23	
24	  useEffect(() => {
25	    setStoredValue(readLocalStorageValue(key, defaultValueRef.current));
26	  }, [key]);
27	
28	  const setValue = useCallback(
29	    (value: SetLocalStorageValue<T>) => {
30	      setStoredValue((currentValue) => {
