19	const AuthCallback = () => {
20	  const navigateTo = useNavigateTo();
21	  const { currentUser, initialize, isInitialized } = useAuth();
22	  const [searchParams] = useSearchParams();
23	  const handledRef = useRef(false);
24	  const [state, setState] = useState<State>({
25	    loading: true,
26	    errorMessage: "",
27	  });
28	
29	  useEffect(() => {
30	    if (!isInitialized) {
31	      return;
32	    }
33	    if (handledRef.current) {
34	      return;
35	    }
36	    // Check for OAuth error response first (e.g., user denied access)
37	    const error = searchParams.get("error");
38	    const errorDescription = searchParams.get("error_description");
39	    const errorUri = searchParams.get("error_uri");
40	
41	    if (error) {
42	      // OAuth provider returned an error
43	      let errorMessage = `OAuth error: ${error}`;
44	      if (errorDescription) {
45	        errorMessage += `\n${decodeURIComponent(errorDescription)}`;
46	      }
47	      if (errorUri) {
48	        errorMessage += `\nMore info: ${errorUri}`;
49	      }
50	
51	      setState({
52	        loading: false,
53	        errorMessage,
54	      });
55	      return;
56	    }
57	
58	    const code = searchParams.get("code");
59	    const state = searchParams.get("state");
60	
61	    if (!code || !state) {
62	      setState({
63	        loading: false,
64	        errorMessage: "Failed to authorize. Missing authorization code or state parameter.",
65	      });
66	      return;
67	    }
68	
69	    // Validate OAuth state (CSRF protection) and retrieve PKCE code_verifier
70	    const validatedState = validateOAuthState(state);
71	    if (!validatedState) {
72	      setState({
73	        loading: false,
74	        errorMessage: "Failed to authorize. Invalid or expired state parameter. This may indicate a CSRF attack attempt.",
75	      });
76	      return;
77	    }
78	
79	    const { flowMode, identityProviderName, returnUrl, linkingUserName, codeVerifier } = validatedState;
80	    const redirectUri = absolutifyLink("/auth/callback");
81	    handledRef.current = true;
82	
83	    (async () => {
84	      try {
85	        if (flowMode === "link") {
86	          if (!currentUser?.name) {
87	            throw new Error("Failed to link account. Please sign in to Memos again and retry.");
88	          }
89	          if (linkingUserName && currentUser.name !== linkingUserName) {
90	            throw new Error("The signed-in user changed before the OAuth callback completed. Please retry linking from account settings.");
91	          }
92	          await userServiceClient.createLinkedIdentity({
93	            parent: currentUser.name,
94	            idpName: identityProviderName,
95	            code,
96	            redirectUri,
97	            codeVerifier: codeVerifier || "",
98	          });
99	        } else {
100	          const response = await authServiceClient.signIn({
101	            credentials: {
102	              case: "ssoCredentials",
103	              value: {
104	                idpName: identityProviderName,
105	                code,
106	                redirectUri,
107	                codeVerifier: codeVerifier || "", // Pass PKCE code_verifier for token exchange
108	              },
109	            },
110	          });
111	          // Store access token from login response
112	          if (response.accessToken) {
113	            setAccessToken(response.accessToken, response.accessTokenExpiresAt ? timestampDate(response.accessTokenExpiresAt) : undefined);
114	          }
115	        }
116	        setState({
117	          loading: false,
118	          errorMessage: "",
119	        });
120	        await initialize();
121	        // Defense-in-depth: even though `returnUrl` was sanitized before being
122	        // stored (see storeOAuthState in SignIn), re-validate on the way out so
123	        // a corrupted state entry can never be used for an open redirect.
124	        navigateTo(getSafeRedirectPath(returnUrl) ?? ROUTES.HOME);
125	      } catch (error: unknown) {
126	        handleError(error, () => {}, {
127	          fallbackMessage: "Failed to authenticate.",
128	          onError: (err) => {
129	            const message = err instanceof Error ? err.message : "Failed to authenticate.";
130	            setState({
131	              loading: false,
132	              errorMessage: message,
133	            });
134	          },
135	        });
136	      }
137	    })();
138	  }, [currentUser?.name, initialize, isInitialized, navigateTo, searchParams]);
139	
140	  if (state.loading) return null;
141	
142	  return (
143	    <div className="p-4 py-24 w-full h-full flex justify-center items-center">
144	      <div className="max-w-lg font-mono whitespace-pre-wrap opacity-80">{state.errorMessage}</div>
145	    </div>
146	  );
147	};
